/* Existing clips are project media, never generated by the workbench. */
let segmentVideoOwner='';
function videoMediaSource(v){const b=P?.media?.[v.path];return b?'data:'+(v.mime||'video/mp4')+';base64,'+b:''}
function syncSegmentVideos(){
 const owner=P?.projectId+':'+seg()?.id,list=$('segmentVideoList');if(!list)return;
 if(owner===segmentVideoOwner)return;segmentVideoOwner=owner;
 const videos=seg()?.videos||[];$('segmentVideoCount').textContent='('+videos.length+')';
 list.innerHTML=videos.map(v=>`<article class="segmentVideoCard"><b>${esc(v.title||v.name)}</b>${videoMediaSource(v)?`<video controls preload="metadata" playsinline src="${videoMediaSource(v)}"></video>`:'<p class="warning">视频文件缺失，请重新添加</p>'}<small>${esc(v.name||'')} · ${((v.size||0)/1048576).toFixed(1)} MB · ${esc(v.createdAt||'')}</small><p class="videoNote">${esc(v.note||'暂无备注')}</p><div class="row"><button data-video-edit="${esc(v.id)}">修改名称 / 备注</button><button data-video-download="${esc(v.id)}">下载视频</button><button data-video-delete="${esc(v.id)}" class="danger">删除记录</button></div></article>`).join('')||'<p class="muted">本片段尚无视频记录。</p>';
}
async function addSegmentVideos(files,targetSegment=null){
 ensure();const project=P,target=targetSegment||seg();if(!target||!project.segments.includes(target))throw Error('先选择片段');const selected=[...files];
 $('segmentVideoStatus').textContent='正在读取视频，请稍候…';
 try{for(const file of selected){
  const ext=file.name.split('.').at(-1).toLowerCase(),mime={mp4:'video/mp4',webm:'video/webm',mov:'video/quicktime'}[ext];
  if(!mime)throw Error('仅支持 MP4 / WebM / MOV');if(file.size>50*1048576)throw Error('单个视频上限 50MB，请先压缩视频');
  const total=project.segments.flatMap(s=>s.videos||[]).reduce((n,v)=>n+(v.size||0),0);if(total+file.size>150*1048576)throw Error('本项目视频合计上限 150MB，请压缩视频后添加');
  const head=new Uint8Array(await file.slice(0,16).arrayBuffer());if(ext==='webm'?![0x1a,0x45,0xdf,0xa3].every((b,i)=>head[i]===b):String.fromCharCode(...head.slice(4,8))!=='ftyp')throw Error('视频文件头无效，请使用标准 MP4 / MOV / WebM 文件');
  const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('视频读取失败'));reader.readAsDataURL(file)});
  if(P!==project||!P.segments.includes(target))throw Error('原项目或片段已切换 / 删除，视频没有写入');
  const id=newId(),path='extra/segment_videos/'+id+'.'+ext;project.media[path]=data.split(',')[1];target.videos||=[];target.videos.push({id,path,mime,name:file.name,title:file.name,note:'',size:file.size,createdAt:new Date().toLocaleString()});changed();
 }
 await flush();segmentVideoOwner='';syncSegmentVideos();toast('视频记录已保存；导出导演包会携带视频文件');
 }finally{$('segmentVideoStatus').textContent='支持浏览器可播放的编码；本项目视频合计上限 150MB。';segmentVideoOwner='';syncSegmentVideos()}
}
$('segmentVideoDrop').onclick=()=>{ensure();$('segmentVideoFile').click()};
$('segmentVideoDrop').onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();$('segmentVideoDrop').click()}};
$('segmentVideoFile').onchange=e=>{const files=[...e.target.files];e.target.value='';safe(()=>addSegmentVideos(files))};
for(const event of ['dragenter','dragover'])$('segmentVideoDrop').addEventListener(event,e=>{e.preventDefault();e.currentTarget.classList.add('dragover')});
$('segmentVideoDrop').ondragleave=e=>e.currentTarget.classList.remove('dragover');
$('segmentVideoDrop').ondrop=e=>{e.preventDefault();e.stopPropagation();e.currentTarget.classList.remove('dragover');safe(()=>addSegmentVideos(e.dataTransfer.files))};
$('segmentVideoList').onclick=e=>safe(async()=>{
 const button=e.target.closest('[data-video-edit],[data-video-delete],[data-video-download]');if(!button)return;
 const target=seg(),project=P,id=button.dataset.videoEdit||button.dataset.videoDelete||button.dataset.videoDownload,v=target.videos.find(v=>v.id===id);if(!v)return;
 if(button.dataset.videoDownload){const source=videoMediaSource(v);if(!source)throw Error('视频文件缺失');const a=document.createElement('a');a.href=source;a.download=v.name;a.click();return}
 if(button.dataset.videoDelete){if(!confirm('删除本片段的这条视频记录？已导出的导演包不受影响。'))return;target.videos=target.videos.filter(x=>x!==v);if(!project.segments.some(s=>(s.videos||[]).some(x=>x.path===v.path)))delete project.media[v.path];changed();await flush();segmentVideoOwner='';syncSegmentVideos();return}
 modal('视频名称与备注',`<label>名称<input id="videoRecordTitle" maxlength="200" value="${esc(v.title||v.name)}"></label><label>记录<textarea id="videoRecordNote" rows="5" maxlength="5000" placeholder="模型、生成版本、提示词、满意之处或待修改内容">${esc(v.note||'')}</textarea></label>`,[{label:'保存',class:'primary',action:async()=>{if(P!==project||!P.segments.includes(target)||!target.videos.includes(v))throw Error('原视频记录已删除或项目已切换');v.title=$('videoRecordTitle').value.trim()||v.name;v.note=$('videoRecordNote').value;changed();await flush();close();segmentVideoOwner='';syncSegmentVideos()}}]);
});
